/**
 * `TableFieldDef` — the discriminated union of field shapes accepted
 * by `table({ fields: [...] })`. Each variant is produced by a
 * dedicated factory in this directory so authors never construct one
 * directly. The serializer routes on `kind` and emits the
 * `TableFieldCreateInput` wire shape.
 *
 * The `kind` discriminator is local-only — it is stripped before the
 * payload reaches the wire (`TableFieldCreateInput` discriminates on
 * which slot is populated, not on a `kind` literal).
 */
import type { AspectFieldSemanticTag, AspectFieldType, TableFieldAggregation, TableFieldExpanded } from "../../../../elementum-entity-client/clients/tables/models/index.js";
import type { FieldRef, TableColumnRef } from "../../../catalog/index.js";
/**
 * Markers the deserializer stamps onto each pulled field so the
 * update serializer can match author-edited fields against their
 * server-side counterparts (`__pulledId`) and reject incompatible
 * kind changes early (`__pulledKind`).
 *
 * Both are author-invisible — hand-authored sources don't set them;
 * the update serializer falls back to a name match in that case.
 * Pulled sources always carry both, so editing a pulled field (even
 * renaming it) round-trips through `updates[]` rather than degrading
 * to `delete + create`.
 *
 * `__pulledKind` is the kind discriminator at pull time. If an author
 * changes `kind: "cloud"` to `kind: "calculation"` in a pulled field,
 * the update serializer raises an error — V3's field-update slot is
 * variant-specific (`{ cloud | calculation | reference }`), and the
 * platform can't switch a field's underlying kind in place.
 */
export interface PulledFieldMarkers {
    readonly __pulledId?: string;
    readonly __pulledKind?: "cloud" | "calculation" | "reference";
}
/**
 * A column directly backed by a cloud table (Snowflake / BigQuery).
 * Created via {@link cloudField}.
 */
export interface TableCloudFieldDef extends PulledFieldMarkers {
    readonly kind: "cloud";
    readonly name: string;
    readonly cloud: {
        readonly snowflake: {
            readonly columnName: string;
            readonly type: AspectFieldType;
        };
    } | {
        readonly bigQuery: {
            readonly columnName: string;
            readonly type: AspectFieldType;
        };
    };
    readonly tags?: readonly AspectFieldSemanticTag[];
}
/**
 * A computed column whose value is derived from other fields via an
 * expression. Created via {@link calculationField}.
 */
export interface TableCalculationFieldDef extends PulledFieldMarkers {
    readonly kind: "calculation";
    readonly name: string;
    /** Calculation expression text (e.g. `"\"qty\" * \"price\""`). */
    readonly expression: string;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
/**
 * A column that references another field (typically on a joined
 * table), optionally aggregating across rows. Created via
 * {@link referenceField}.
 */
export interface TableReferenceFieldDef extends PulledFieldMarkers {
    readonly kind: "reference";
    readonly name: string;
    /**
     * Id of the source field this column projects from, an app/element field
     * token, or a table-column token resolved at apply.
     */
    readonly source: string | {
        readonly id: string;
    } | FieldRef | TableColumnRef;
    readonly aggregation?: TableFieldAggregation;
    readonly expanded?: TableFieldExpanded;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export type TableFieldDef = TableCloudFieldDef | TableCalculationFieldDef | TableReferenceFieldDef;
